contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool sent = false;
        c.sendMoney(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sent = false;
        } else {
            sent = true;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(sent && afterDeposits == beforeDeposits && afterBalance + amount == beforeBalance);
    }

    receive() external payable {}
}

